package main

import (
	"bufio"
	"fmt"
	"os"
)

type Scanner struct {
	reader *bufio.Reader
	buffer []string
}

func NewScanner(reader *bufio.Reader) *Scanner {
	return &Scanner{
		reader: reader,
		buffer: []string{},
	}
}

func (s *Scanner) token() string {
	for {
		if len(s.buffer) > 0 {
			tok := s.buffer[len(s.buffer)-1]
			s.buffer = s.buffer[:len(s.buffer)-1]
			return tok
		}
		line, err := s.reader.ReadString('\n')
		if err != nil {
			panic("Failed read")
		}
		start := -1
		s.buffer = s.buffer[:0]
		for i, c := range line {
			if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
				if start != -1 {
					s.buffer = append(s.buffer, line[start:i])
					start = -1
				}
			} else if start == -1 {
				start = i
			}
		}
		if start != -1 {
			s.buffer = append(s.buffer, line[start:len(line)])
		}
		for i, j := 0, len(s.buffer)-1; i < j; i, j = i+1, j-1 {
			s.buffer[i], s.buffer[j] = s.buffer[j], s.buffer[i]
		}
	}
}

func factorize(n int64) []int64 {
	ans := []int64{}
	var d int64 = 2
	for d*d <= n {
		for n%d == 0 {
			ans = append(ans, d)
			n /= d
		}
		d++
	}
	if n > 1 {
		ans = append(ans, n)
	}
	return ans
}

func solve(scan *Scanner, out *bufio.Writer) {
	var n, k int64
	fmt.Sscan(scan.token(), &n)
	fmt.Sscan(scan.token(), &k)

	factors := factorize(n)
	numFactors := int64(len(factors))
	if numFactors < k {
		fmt.Fprintln(out, "-1")
		out.Flush()
		return
	}
	for i := int64(0); i < k-1; i++ {
		fmt.Fprintf(out, "%d ", factors[i])
	}
	lastFactor := int64(1)
	for i := k - 1; i < numFactors; i++ {
		lastFactor *= factors[i]
	}
	fmt.Fprintln(out, lastFactor)
	out.Flush()
}

func main() {
	stdin := os.Stdin
	stdout := os.Stdout
	scan := NewScanner(bufio.NewReader(stdin))
	out := bufio.NewWriter(stdout)
	solve(scan, out)
}

